                    //根据选择的卡牌的花色 判断要转化出的卡牌是闪还是神杀还是无懈还是桃
                    switch (cards[0]?.suit) {
                        case 'club':
                            name = 'shan';
                            break;
                        case 'diamond':
                            name = 'sha';
                            nature = 'kami';
                            break;
                        case 'spade':
                            name = 'wuxie';
                            break;
                        case 'heart':
                            name = 'tao';
                            break;
                    }
                    //返回判断结果
                    if (name) return { name: name, nature: nature };
                    return null;
