            tgtt_fsdzsujian: {
                trigger: {
                    player: 'phaseDiscardBefore',
                },
                audio: 'ext:太古天庭/audio/skill/tgtt_fsdengzhi:2',
                forced: true,
                charlotte: true,
                content() {
                    trigger.setContent(lib.skill.tgtt_fsdzsujian.phaseDiscard);
                },
                phaseDiscard() {
                    'step 0';
                    player.changeHujia();
                    player.draw();
                    player.recover();
                    game.log(player, '进入了弃牌阶段');
                    game.broadcastAll(function (player) {
                        if (lib.config.show_phase_prompt) {
                            player.popup('弃牌阶段', null, false);
                        }
                    }, player);
                    event.trigger('phaseDiscard');
                    ('step 1');
                    var cards = lib.skill.tgtt_fsdzsujian.update(player);
                    if (!cards.length) event.finish();
                    else {
                        event.cards = cards;
                        var str = get.translation(cards);
                        player
                            .chooseControl()
                            .set('choiceList', ['将' + str + '分配给任意名其他角色', '弃置' + str + '并弃置一名其他角色至多等量的牌'])
                            .set('ai', function () {
                                var cards = _status.event.parent.cards,
                                    player = _status.event.player;
                                if (
                                    !game.hasPlayer(function (current) {
                                        return get.attitude(player, current) > 0;
                                    })
                                )
                                    return 1;
                                if (
                                    game.hasPlayer(function (current) {
                                        var att = get.attitude(player, current);
                                        return (
                                            att != 0 &&
                                            current.countDiscardableCards(player, 'he', function (i) {
                                                if (att > 0) return get.value(i, current) >= 4;
                                                return get.value(i, current) <= 0;
                                            }) >= cards.length &&
                                            get.effect(current, { name: 'guohe_copy2' }, player, player) > 0
                                        );
                                    })
                                )
                                    return 1;
                                return 0;
                            });
                    }
                    ('step 2');
                    if (result.index == 1) {
                        cards = event.cards.filter(function (i) {
                            return lib.filter.cardDiscardable(i, player, 'tgtt_fsdzsujian');
                        });
                        if (cards.length) {
                            event.num = cards.length;
                            player.discard(cards);
                            event.cards = cards;
                        } else event.finish();
                    } else event.goto(5);
                    ('step 3');
                    if (
                        game.hasPlayer(function (current) {
                            return current != player && current.countDiscardableCards(player, 'he') > 0;
                        })
                    ) {
                        player
                            .chooseTarget(true, '弃置一名其他角色的至多' + get.cnNumber(num) + '张牌', function (card, player, current) {
                                return current != player && current.countDiscardableCards(player, 'he') > 0;
                            })
                            .set('ai', function (current) {
                                var att = get.attitude(player, current);
                                if (
                                    current.countDiscardableCards(player, 'he', function (i) {
                                        if (att > 0) return get.value(i, current) >= 4;
                                        return get.value(i, current) <= 0;
                                    }) >= num
                                )
                                    return 4 * get.effect(current, { name: 'guohe_copy2' }, player, player);
                                return get.effect(current, { name: 'guohe_copy2' }, player, player);
                            });
                    } else event.finish();
                    ('step 4');
                    if (result.targets?.length) {
                        var target = result.targets[0];
                        player.line(target, 'green');
                        player.discardPlayerCard(target, true, [1, num]);
                    }
                    event.finish();
                    ('step 5');
                    if (_status.connectMode)
                        game.broadcastAll(function () {
                            _status.noclearcountdown = true;
                        });
                    event.given_map = {};
                    ('step 6');
                    player.chooseCardTarget({
                        filterCard(card) {
                            return card.hasGaintag('tgtt_fsdzsujian');
                        },
                        filterTarget: lib.filter.notMe,
                        selectCard: [1, cards.length],
                        forced: true,
                        prompt: '请选择要分配的卡牌和目标',
                        ai1(card) {
                            if (!ui.selected.cards.length) return 1;
                            return 0;
                        },
                        ai2(target) {
                            var player = _status.event.player,
                                card = ui.selected.cards[0];
                            var val = target.getUseValue(card);
                            if (val > 0) return val * get.attitude(player, target) * 2;
                            return get.value(card, target) * get.attitude(player, target);
                        },
                    });
                    ('step 7');
                    if (result.cards?.length) {
                        var res = result.cards,
                            target = result.targets[0].playerid;
                        player.removeGaintag('tgtt_fsdzsujian', res);
                        player.addGaintag(res, 'tgtt_fsdzsujian_given');
                        cards.removeArray(res);
                        if (!event.given_map[target]) event.given_map[target] = [];
                        event.given_map[target].addArray(res);
                        if (cards.length) event.goto(6);
                    } else event.finish();
                    ('step 8');
                    if (_status.connectMode) {
                        game.broadcastAll(function () {
                            delete _status.noclearcountdown;
                            game.stopCountChoose();
                        });
                    }
                    var map = [],
                        cards = [];
                    for (var i in event.given_map) {
                        var source = (_status.connectMode ? lib.playerOL : game.playerMap)[i];
                        player.line(source, 'green');
                        map.push([source, event.given_map[i]]);
                        cards.addArray(event.given_map[i]);
                    }
                    if (map.length)
                        game.loseAsync({
                            gain_list: map,
                            player: player,
                            cards: cards,
                            giver: player,
                            addTempClass: 'giveAuto',
                        }).setContent('gaincardMultiple');
                    ('step 9');
                    event.cards = [];
                },
                update(player) {
                    player.removeGaintag('tgtt_fsdzsujian');
                    var hs = player.getCards('h');
                    player.getHistory('gain', function (evt) {
                        hs.removeArray(evt.cards);
                    });
                    if (hs.length) player.addGaintag(hs, 'tgtt_fsdzsujian');
                    return hs;
                },
                group: 'tgtt_fsdzsujian_sync',
                subSkill: {
                    sync: {
                        trigger: {
                            player: ['phaseBeginStart', 'gainBegin'],
                        },
                        forced: true,
                        charlotte: true,
                        popup: false,
                        firstDo: true,
                        filter(event, player) {
                            if (event.name == 'gain') return player == _status.currentPhase && event.getParent('tgtt_fsdzsujian').player != player;
                            return true;
                        },
                        content() {
                            lib.skill.tgtt_fsdzsujian.update(player);
                        },
                    },
                },
            },
