            tgtt_mtxuanze_append: '<span class="text" style="font-family: yuanli">命途技能:</br><li><font color=red>「毁灭」</font>:<font color=red>【毁灭】</font>;</br><li><font color=green>「巡猎」</font>:<font color=green>【巡猎】</font>;</br><li><font color=yellow>「智识」</font>:<font color=yellow>【智识】</font>;</br><li><font color=orange>「繁育」</font>:<font color=orange>【繁育】</font>;</br><li><font color=cyan>「丰饶」</font>:<font color=cyan>【丰饶】</font>;</br><li><font color=blue>「记忆」</font>:<font color=blue>【记忆】</font>;</br><li><font color=grey>「存护」</font>:<font color=grey>【存护】</font>;</br><li><samp id=\'「欢愉」\'><big><strong>「欢愉」</strong></big></samp></body><style>#「欢愉」{animation:change 10s linear 0s infinite;font-family:shousha;}@keyframes change{0% {color: #FF0000;}10%{color: #FF7F00;}20%{color: #FFFF00;}30%{color: #00FF00;}40% {color: #00FFFF;}50%{color: #0000FF;}60%{color: #8B00FF;}70%{color: #0000FF;}75%{color: #00FFFF ;}80%{color: #00FF00;}85%{color: #FFFF00 ;}90%{color:  #FF7F00;}100%{color: #FF0000;}}</style></span>:<samp id=\'【欢愉】\'><big><strong>【欢愉】</strong></big></samp></body><style>#【欢愉】{animation:change 10s linear 0s infinite;font-family:shousha;}@keyframes change{0% {color: #FF0000;}10%{color: #FF7F00;}20%{color: #FFFF00;}30%{color: #00FF00;}40% {color: #00FFFF;}50%{color: #0000FF;}60%{color: #8B00FF;}70%{color: #0000FF;}75%{color: #00FFFF ;}80%{color: #00FF00;}85%{color: #FFFF00 ;}90%{color:  #FF7F00;}100%{color: #FF0000;}}</style></span>;</br><li><font color=white>「虚无」</font>:<font color=white>【虚无】</font>',
            tgtt_mtxuanze_faq: '命途技能',
            tgtt_mtxuanze_faq_info: "</br><li><font color=red>「毁灭」</font>:<font color=red>【毁灭】</font>;</br><li><font color=green>「巡猎」</font>:<font color=green>【巡猎】</font>;</br><li><font color=yellow>「智识」</font>:<font color=yellow>【智识】</font>;</br><li><font color=orange>「繁育」</font>:<font color=orange>【繁育】</font>;</br><li><font color=cyan>「丰饶」</font>:<font color=cyan>【丰饶】</font>;</br><li><font color=blue>「记忆」</font>:<font color=blue>【记忆】</font>;</br><li><font color=grey>「存护」</font>:<font color=grey>【存护】</font>;</br><li><samp id='「欢愉」'><big><strong>「欢愉」</strong></big></samp></body><style>#「欢愉」{animation:change 10s linear 0s infinite;font-family:shousha;}@keyframes change{0% {color: #FF0000;}10%{color: #FF7F00;}20%{color: #FFFF00;}30%{color: #00FF00;}40% {color: #00FFFF;}50%{color: #0000FF;}60%{color: #8B00FF;}70%{color: #0000FF;}75%{color: #00FFFF ;}80%{color: #00FF00;}85%{color: #FFFF00 ;}90%{color:  #FF7F00;}100%{color: #FF0000;}}</style></span>:<samp id='【欢愉】'><big><strong>【欢愉】</strong></big></samp></body><style>#【欢愉】{animation:change 10s linear 0s infinite;font-family:shousha;}@keyframes change{0% {color: #FF0000;}10%{color: #FF7F00;}20%{color: #FFFF00;}30%{color: #00FF00;}40% {color: #00FFFF;}50%{color: #0000FF;}60%{color: #8B00FF;}70%{color: #0000FF;}75%{color: #00FFFF ;}80%{color: #00FF00;}85%{color: #FFFF00 ;}90%{color:  #FF7F00;}100%{color: #FF0000;}}</style></span>;</br><li><font color=white>「虚无」</font>:<font color=white>【虚无】</font>",
            tgtt_huaxialongyou: '华夏龙佑',
            tgtt_huaxialongyou_info: '锁定技,你的非太古天庭技能失效',
            tgtt_dylinghunshoulie: '灵魂狩猎',
